// สร้างข้อความเตือนจากผล Check Temp Bounds — โค้ดล้วน ไม่มี AI ไม่มีค่า token
// เกาะไปกับ Telemetry Sync ที่รันทุก 15 นาที จึงรู้เร็วกว่ารายงาน AI ทุก 4 ชม.ถึง 16 เท่า
// (เจอจริง 8 ก.ย.: เบียร์หลุดต่ำกว่าขีดล่างยีสต์ตั้งแต่ ~09:00 แต่กว่าจะรู้คือรายงาน 18:01)
const COLOR = { sensor_stale: 0x95a5a6, controller_lag: 0xe74c3c, rapid_change: 0xe74c3c,
                yeast_low: 0xe67e22, yeast_high: 0xe67e22,
                band_low: 0xf1c40f, band_high: 0xf1c40f,
                drifting_low: 0x3498db, drifting_high: 0x3498db,
                arrived: 0x2ecc71, ok: 0x2ecc71 };
// ดันให้เข้ามาในช่วงยีสต์ 0.5°C ไม่ใช่จ่อขอบพอดี กันแกว่งออกอีกรอบทันที
const INSIDE_MARGIN_C = 0.5;
// จำกัดการขยับต่อครั้ง — ข้อเสนอมาจากสูตรคำนวณ ไม่ใช่คนดูของจริง อย่าให้สั่งกระโดดไกล
const MAX_NUDGE_C = 2.0;
// ขั้นต่ำที่ยอมเสนอ — 0.2°C คือ 2 สเต็ปของความละเอียดที่ RAPT ตั้ง target ได้ (0.1°C)
// เดิมตั้ง 0.5 ด้วยเหตุผลว่า "จมไปกับ hysteresis ของตู้" ซึ่งถูกแค่ครึ่งเดียว — hysteresis
// ทำให้ค่า "ณ ขณะหนึ่ง" แกว่ง แต่ไม่ได้ทำให้ "ค่าเฉลี่ยที่สมดุล" ขยับตาม การเลื่อน target
// 0.25°C จึงเลื่อนอุณหภูมิเบียร์ที่สมดุลไป 0.25°C จริง แค่ไม่เห็นผลทันทีในจุดเดียว
// (ต่างจากเกณฑ์ 0.5 ของ Brew Master ที่เสนอการแก้ระดับเฟส ซึ่งเป็นการขยับหลักองศา)
const MIN_NUDGE_C = 0.2;

function f(v, n) { return v == null ? '-' : Number(v).toFixed(n); }

const results = [];
$input.all().forEach((it) => {
  const d = it.json;
  // โหมดแจ้งทุกรอบส่งแถวเดิมซ้ำได้เรื่อยๆ ระหว่างที่สถานการณ์ยังไม่เปลี่ยน — ติดป้ายไว้
  // ไม่งั้นข้อความหน้าตาเหมือนกันเป๊ะทุก 15 นาทีจะอ่านเหมือนเหตุใหม่เกิดซ้ำๆ
  // (แถว ok ไม่ต้องติด เพราะตัวมันเองคือ "รายงานสถานะประจำรอบ" อยู่แล้ว)
  const isRepeat = d.alert_kind !== 'ok' && d.is_fresh_alert === false;
  const pill = d.pill_c != null ? Number(d.pill_c) : null;
  const tgt = d.target_c != null ? Number(d.target_c) : null;
  let title, lines = [], wantPill = null;

  switch (d.alert_kind) {
    case 'sensor_stale':
      title = '📡 เซ็นเซอร์เงียบ — ' + d.beer_name;
      lines.push('Pill เงียบมา ' + f(d.pill_age_h, 1) + ' ชม. · ตู้ควบคุม ' + f(d.ctrl_age_h, 1) + ' ชม.');
      lines.push('ค่าที่ระบบใช้วิเคราะห์ตอนนี้เป็นข้อมูลค้าง — เช็คแบต Pill / WiFi / ปลั๊กตู้ แล้วดูใน RAPT portal ว่า device ยัง online ไหม');
      break;
    case 'controller_lag':
      title = '🔴 ตู้ควบคุมไล่อุณหภูมิไม่ถึงเป้า — ' + d.beer_name;
      lines.push('ตู้ ' + f(d.ctrl_c, 2) + '°C ห่างจาก target ' + f(d.target_c, 2) + '°C อยู่ ' + f(d.ctrl_dev_c, 2) + '°C มาเกิน 1 ชม.และไม่ลดลง');
      lines.push('ไม่ใช่การไล่อุณหภูมิตามคำสั่งปกติ — ไปดูของจริง: คอมเพรสเซอร์ทำงานไหม ประตูปิดสนิทไหม ของในตู้แน่นเกินไปหรือเปล่า');
      lines.push('**อย่าเพิ่งปรับ target** เพราะปัญหาไม่ได้อยู่ที่ค่าที่ตั้ง');
      break;
    case 'rapid_change':
      title = '🔴 อุณหภูมิเบียร์เปลี่ยนเร็วผิดปกติ — ' + d.beer_name;
      lines.push('Pill ขยับ ' + f(d.pill_move_1h_c, 2) + '°C ใน 1 ชม. ทั้งที่ target ไม่ได้เปลี่ยน (ปกติไม่เกิน 1.5°C/ชม.)');
      lines.push('ล่าสุด ' + f(d.pill_c, 2) + '°C — เปิดประตูตู้ค้างไว้หรือเปล่า หรือระบบทำความเย็น/ฮีตเตอร์มีปัญหา');
      break;
    case 'yeast_low':
      title = '⚠️ อุณหภูมิเบียร์ต่ำกว่าที่ยีสต์รองรับ — ' + d.beer_name;
      lines.push('เบียร์ ' + f(d.pill_c, 2) + '°C ต่ำกว่าขีดล่าง ' + f(d.yeast_min, 0) + '°C อยู่ ' + f(Number(d.yeast_min) - pill, 2) + '°C');
      lines.push('เสี่ยงยีสต์ทำงานช้าลง ตกก้นก่อนกินน้ำตาลหมด หรือเก็บ diacetyl ไม่หมด');
      wantPill = Number(d.yeast_min) + INSIDE_MARGIN_C;
      break;
    case 'yeast_high':
      title = '⚠️ อุณหภูมิเบียร์สูงกว่าที่ยีสต์รองรับ — ' + d.beer_name;
      lines.push('เบียร์ ' + f(d.pill_c, 2) + '°C สูงกว่าขีดบน ' + f(d.yeast_max, 0) + '°C อยู่ ' + f(pill - Number(d.yeast_max), 2) + '°C');
      lines.push('เสี่ยง fusel alcohol (กลิ่นแสบ ดื่มแล้วปวดหัว) และ ester แรงเกินสไตล์');
      wantPill = Number(d.yeast_max) - INSIDE_MARGIN_C;
      break;
    case 'band_low':
    case 'band_high': {
      // ช่วงที่ผู้หมักตั้งเองผ่าน /ferment_band — เตือนแบบ "เฝ้าดู" เพราะยังไม่หลุดสเปกยีสต์
      const lo = Number(d.band_low), hi = Number(d.band_high);
      const below = d.alert_kind === 'band_low';
      title = '👀 อุณหภูมิเบียร์หลุดช่วงที่ตั้งไว้ — ' + d.beer_name;
      lines.push('เบียร์ ' + f(d.pill_c, 2) + '°C ' + (below ? 'ต่ำกว่า' : 'สูงกว่า') + 'ช่วงที่ตั้งไว้ '
        + f(lo, 2) + '-' + f(hi, 2) + '°C อยู่ ' + f(below ? lo - pill : pill - hi, 2) + '°C');
      lines.push(d.yeast_min != null
        ? ('(ยังอยู่ในช่วงที่ยีสต์รองรับ ' + f(d.yeast_min, 0) + '-' + f(d.yeast_max, 0) + '°C จึงยังไม่ถึงขั้นอันตราย)')
        : '(ไม่มีข้อมูลช่วงยีสต์มาเทียบ)');
      // เล็งกลางช่วง ไม่ใช่จ่อขอบ จะได้ไม่หลุดออกอีกทันทีที่แกว่งนิดเดียว
      wantPill = (lo + hi) / 2;
      break;
    }
    case 'drifting_low':
    case 'drifting_high': {
      // เตือน "ก่อน" หลุด ไม่ใช่หลังหลุด — ต่างจาก kind อื่นที่รอให้ข้ามเส้นก่อน
      // ค่าที่ใช้คาดการณ์มาจาก linear regression 3 ชม.ล่าสุด ไม่ใช่หัวท้าย 2 จุด
      const down = d.alert_kind === 'drifting_low';
      const edge = down ? Number(d.floor_c) : Number(d.ceil_c);
      const hrs = down ? Number(d.hours_to_floor) : Number(d.hours_to_ceil);
      const edgeIsYeast = down
        ? (d.yeast_min != null && Number(d.yeast_min) >= Number(d.band_low ?? -999))
        : (d.yeast_max != null && Number(d.yeast_max) <= Number(d.band_high ?? 999));
      title = (down ? '🔻 อุณหภูมิเบียร์กำลังไหลลง' : '🔺 อุณหภูมิเบียร์กำลังไต่ขึ้น') + ' — ' + d.beer_name;
      lines.push('เบียร์ ' + f(d.pill_c, 2) + '°C ' + (down ? 'ลดลง ' : 'เพิ่มขึ้น ')
        + f(Math.abs(Number(d.rate_c_per_h)), 2) + '°C/ชม. (คิดจากแนวโน้ม 3 ชม.ล่าสุด)');
      lines.push(hrs <= 0.1
        ? ('ตอนนี้อยู่ที่' + (down ? 'ขอบล่าง ' : 'ขอบบน ') + f(edge, 2) + '°C พอดีและยังเคลื่อนต่อ — กำลังจะหลุด'
           + (edgeIsYeast ? ' ซึ่งเป็นขีดของยีสต์ด้วย' : ''))
        : ('คาดว่าจะแตะ' + (down ? 'ขอบล่าง ' : 'ขอบบน ') + f(edge, 2) + '°C ในอีก ~' + f(hrs, 1) + ' ชม.'
           + (edgeIsYeast ? ' ซึ่งเป็นขีดของยีสต์ด้วย' : '')));
      lines.push('ยังไม่หลุด แต่เตือนไว้ก่อนจะได้แก้ทัน');
      // เล็งกลางช่วงที่ใช้ได้จริง ถ้ารู้ทั้งสองขอบ ไม่งั้นถอยเข้ามาจากขอบ 0.5°C
      wantPill = (d.floor_c != null && d.ceil_c != null)
        ? (Number(d.floor_c) + Number(d.ceil_c)) / 2
        : (down ? Number(d.floor_c) + INSIDE_MARGIN_C : Number(d.ceil_c) - INSIDE_MARGIN_C);
      break;
    }
    case 'ok': {
      // โหมด "แจ้งทุกรอบ" (bot_state.temp_guard_report_mode = 'always') — ไม่ใช่ alert
      // มีไว้ยืนยันว่าระบบยังเดินอยู่ ปิดได้ด้วย SQL บรรทัดเดียวโดยไม่ต้อง reimport
      title = '✅ ปกติ — ' + d.beer_name;
      lines.push('เบียร์ ' + f(d.pill_c, 2) + '°C'
        + (d.band_low != null ? ('  ช่วงที่ตั้ง ' + f(d.band_low, 2) + '-' + f(d.band_high, 2) + ' ✅') : '')
        + (d.yeast_min != null ? ('  ยีสต์ ' + f(d.yeast_min, 0) + '-' + f(d.yeast_max, 0) + ' ✅') : ''));
      lines.push('ตู้ ' + f(d.ctrl_c, 2) + '°C (target ' + f(d.target_c, 2) + '°C, เบี่ยง ' + f(d.ctrl_dev_c, 2) + '°C)');
      if (d.rate_c_per_h != null && Math.abs(Number(d.rate_c_per_h)) >= 0.05) {
        const rt = Number(d.rate_c_per_h);
        lines.push('แนวโน้ม ' + (rt < 0 ? 'ลดลง ' : 'เพิ่มขึ้น ') + f(Math.abs(rt), 2) + '°C/ชม.'
          + (rt < 0 && d.hours_to_floor != null ? (' · ถึงขอบล่างในอีก ~' + f(d.hours_to_floor, 1) + ' ชม.') : '')
          + (rt > 0 && d.hours_to_ceil != null ? (' · ถึงขอบบนในอีก ~' + f(d.hours_to_ceil, 1) + ' ชม.') : ''));
      } else {
        lines.push('แนวโน้ม: นิ่ง');
      }
      lines.push('ข้อมูล Pill ' + f(Number(d.pill_age_h) * 60, 0) + ' นาทีก่อน · ตู้ ' + f(Number(d.ctrl_age_h) * 60, 0) + ' นาทีก่อน');
      break;
    }
    case 'arrived':
      title = '✅ อุณหภูมิเบียร์นิ่งแล้ว — ' + d.beer_name;
      lines.push('เบียร์นิ่งที่ ' + f(d.pill_c, 2) + '°C (ขยับ ' + f(d.pill_move_1h_c, 2) + '°C ใน 1 ชม.ล่าสุด) หลังตั้ง target ' + f(d.target_c, 2) + '°C มา ' + f(d.tgt_stable_h, 1) + ' ชม.');
      lines.push('ถึงที่หมายแล้ว เริ่มนับเวลาของเฟสนี้ได้');
      break;
    default:
      return;
  }

  // target ใหม่แบบ "ขยับสัมพัทธ์" — ไม่ต้องรู้ส่วนต่าง Pill-ตู้เลย เพราะอยากให้เบียร์ขึ้นเท่าไหร่
  // ก็ขยับ target ขึ้นเท่านั้น ส่วนต่างหักล้างกันไปเอง (ต่างจากการแปลงแบบสัมบูรณ์ที่ต้องใช้
  // stable_gap_c ซึ่งมักไม่มีค่าในช่วง 2 ชม.แรกหลังปรับ target)
  // เสนอขยับได้เฉพาะตอนตู้ไล่ถึง target แล้วจริง — ถ้ายังไล่ไม่ถึง เบียร์กำลังจะขยับเองอยู่แล้ว
  // การขยับ target ซ้ำตอนนั้นจะ over-correct (เจอจริง 8 ก.ย.: ตู้ 15.98 vs target 16.50 ถ้าไล่
  // ถึง 16.50 เบียร์จะขึ้นไป ~18.2 เองโดยไม่ต้องทำอะไร)
  const ctrlSettled = d.ctrl_c != null && tgt != null && Math.abs(Number(d.ctrl_c) - tgt) <= 0.5;
  let buttonTarget = null;
  if (d.alert_kind === 'ok') wantPill = null;   // แถวสถานะปกติ ไม่เสนออะไร
  if (wantPill != null && !ctrlSettled) {
    lines.push('⏳ ยังไม่เสนอปรับ target — ตู้อยู่ ' + f(d.ctrl_c, 2) + '°C ยังไล่ไม่ถึง target ' + f(tgt, 2) + '°C เบียร์อาจขยับเข้าที่เองเมื่อตู้ถึงเป้า');
  }
  if (wantPill != null && ctrlSettled && pill != null && tgt != null) {
    let nudge = Math.max(-MAX_NUDGE_C, Math.min(MAX_NUDGE_C, wantPill - pill));
    // เคสกำลังไหลไปหาขอบ: ถ้าการขยับที่ต้องการเล็กกว่าขั้นต่ำ ให้ "ดันขึ้นเป็นขั้นต่ำ" ไม่ใช่
    // ทิ้งปุ่มไป — เพราะเราส่งข้อความเตือนไปแล้วว่ากำลังจะหลุด การเตือนแล้วไม่บอกว่าให้ทำอะไร
    // คือแย่ที่สุดของทั้งสองทาง (เจอจริง 8 ก.ย.: ต้องขยับ +0.19°C ถูกตัดทิ้งเพราะเกณฑ์ 0.20
    // ทั้งที่เบียร์กำลังจะนิ่งพอดีที่ขอบล่างซึ่งไม่เหลือ margin เลย)
    // ส่วนเคสที่หลุดไปแล้วแต่นิ่ง (band_high เกินไป 0.11°C) ยังคงเงียบเหมือนเดิม เพราะการ
    // ดันเป็น 0.2 จะกลายเป็นแก้เกินจำเป็น
    const isDrift = d.alert_kind === 'drifting_low' || d.alert_kind === 'drifting_high';
    if (isDrift) {
      // ทิศทางต้องสวนกับที่ไหลเสมอ — เบียร์ไหลลงต้องดัน target ขึ้น ไม่ใช่ลง
      // เคสที่ทำให้ผิดทางได้: เบียร์ยังอยู่เหนือกลางช่วงแต่กำลังไหลลง (เช่น 18.40 ในช่วง
      // 18.0-18.5) สูตร wantPill - pill จะได้ค่าติดลบ = สั่งลด target ซึ่งยิ่งเร่งให้หลุด
      const want = d.alert_kind === 'drifting_low' ? 1 : -1;
      if (Math.sign(nudge) !== want || Math.abs(nudge) < MIN_NUDGE_C) nudge = want * MIN_NUDGE_C;
    }
    const t = Number((tgt + nudge).toFixed(2));
    // ปัดก่อนเทียบ ไม่งั้น 16.50 - 16.30 = 0.19999999999999929 ใน floating point แล้วตกเกณฑ์
    // 0.2 ไปเฉยๆ (เจอจริง 8 ก.ย. ปุ่มไม่ขึ้นทั้งที่คำนวณมาถูกทุกขั้น)
    const delta = Math.round(Math.abs(t - tgt) * 100) / 100;
    if (delta >= MIN_NUDGE_C && t >= 0 && t <= 30) buttonTarget = t;
  }
  if (buttonTarget != null) {
    lines.push('🌡️ เสนอปรับ target ตู้เป็น ' + f(buttonTarget, 2) + '°C (ขยับ ' + (buttonTarget > tgt ? '+' : '') + f(buttonTarget - tgt, 2) + '°C เพื่อดันเบียร์ไปที่ ~' + f(wantPill, 2) + '°C)');
  }

  results.push({
    json: {
      batch_id: d.batch_id,
      alert_kind: d.alert_kind,
      button_target_c: buttonTarget,
      embeds: [{
        title: title.length > 256 ? title.slice(0, 255) + '…' : title,
        color: COLOR[d.alert_kind] || 0x95a5a6,
        description: lines.join('\n').slice(0, 4096),
        footer: { text: 'เฟส ' + (d.current_phase || '-') + ' · ตรวจทุก 15 นาทีโดย Temp Guard'
          + (isRepeat ? ' · แจ้งซ้ำจากโหมดแจ้งทุกรอบ' : '') }
      }]
    }
  });
});
return results;
